const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret || secret.length < 16) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET is not configured in n8n environment.');
}

const item = $input.first();
const headers = item.json.headers || {};
const sigHeader = headers['x-lendloop-signature'] || '';
const tsHeader = headers['x-lendloop-timestamp'] || '';
const bodyObj = item.json.body || {};
const rawBody = item.binary?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(bodyObj);

if (!sigHeader || !tsHeader) {
  throw new Error('Unauthorized: Missing X-LendLoop-Signature or X-LendLoop-Timestamp header.');
}

const nowSec = Math.floor(Date.now() / 1000);
const reqSec = Number(tsHeader);
if (!Number.isFinite(reqSec) || Math.abs(nowSec - reqSec) > 300) {
  throw new Error(`Unauthorized: Webhook timestamp outside 300s replay window (skew=${nowSec - reqSec}s).`);
}

const providedHex = String(sigHeader).trim().toLowerCase().replace(/^sha256=/, '');
const expectedHex = crypto
  .createHmac('sha256', secret)
  .update(`${tsHeader}.${rawBody}`)
  .digest('hex');

const a = Buffer.from(providedHex, 'utf8');
const b = Buffer.from(expectedHex, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Unauthorized: Invalid HMAC-SHA256 webhook signature.');
}

// Strict Data Minimization: Extract only the fields required for notification
const {
  eventId,
  eventType,
  loanId,
  toolName,
  toolCategory,
  status,
  startDate,
  endDate,
  recipientRole,
  recipientName,
  recipientEmail,
  counterpartyName,
  note
} = bodyObj;

const templates = {
  'loan.requested': {
    subject: `[LendLoop] ${counterpartyName} requested to borrow your ${toolName}`,
    message: `Hi ${recipientName}, ${counterpartyName} requested to borrow your ${toolName} (${toolCategory}) from ${startDate} to ${endDate}.${note ? ' Note: ' + note : ''}`,
    activitySummary: `Request notification sent to lender (${recipientName})`
  },
  'loan.approved': {
    subject: `[LendLoop] Approved! Your request for ${toolName} is confirmed`,
    message: `Hi ${recipientName}, ${counterpartyName} approved your borrow request for ${toolName} (${startDate} to ${endDate}).`,
    activitySummary: `Approval notification sent to borrower (${recipientName})`
  },
  'loan.declined': {
    subject: `[LendLoop] Update on your request for ${toolName}`,
    message: `Hi ${recipientName}, ${counterpartyName} was unable to approve your request for ${toolName} (${startDate} to ${endDate}).`,
    activitySummary: `Decline notification sent to borrower (${recipientName})`
  },
  'loan.returned': {
    subject: `[LendLoop] Return confirmed for ${toolName}`,
    message: `Hi ${recipientName}, ${counterpartyName} marked ${toolName} as returned. Thanks for keeping LendLoop running smoothly!`,
    activitySummary: `Return confirmation sent to borrower (${recipientName})`
  }
};

const tpl = templates[eventType] || {
  subject: `[LendLoop] Update for ${toolName}`,
  message: `Status changed to ${status} for ${toolName}.`,
  activitySummary: `Notification processed (${eventType})`
};

return [{
  json: {
    eventId,
    eventType,
    loanId,
    recipientRole,
    recipientName,
    recipientEmail,
    subject: tpl.subject,
    message: tpl.message,
    activitySummary: tpl.activitySummary
  }
}];

const crypto = require('crypto');
const item = $input.first().json;

// Deliver structured notification (can also be wired to SMTP / Slack / Discord credentials in n8n)
console.log(JSON.stringify({
  channel: 'lendloop_notification',
  to: item.recipientEmail,
  subject: item.subject,
  body: item.message,
  eventId: item.eventId,
  deliveredAt: new Date().toISOString()
}));

const callbackPayload = {
  idempotencyKey: `n8n-ack:${item.eventId}`,
  loanId: item.loanId,
  workflow: 'request_notification',
  eventType: item.eventType,
  status: 'delivered',
  summary: item.activitySummary,
  attemptCount: 1
};

const rawCallbackBody = JSON.stringify(callbackPayload);
const ts = String(Math.floor(Date.now() / 1000));
const sig = 'sha256=' + crypto
  .createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET)
  .update(`${ts}.${rawCallbackBody}`)
  .digest('hex');

return [{
  json: {
    callbackUrl: `${$env.CONVEX_SITE_URL}/api/n8n/automation-events`,
    rawCallbackBody,
    ts,
    sig,
    idempotencyKey: callbackPayload.idempotencyKey
  }
}];
